       father_name text,mother_name text,parent_phone text,enrollment_date date)
)
insert into public.app3_students
(student_code,full_name,dob,gender,class_id,grade,address,father_name,mother_name,parent_phone,enrollment_date,status)
select src.code,src.name,src.dob,src.gender,c.id,src.grade,
       nullif(src.address,''),nullif(src.father_name,''),nullif(src.mother_name,''),
       nullif(src.parent_phone,''),src.enrollment_date,'Đang học'
from src
join public.app3_classes c on upper(c.name)=upper(src.cls)
where not exists (select 1 from public.app3_students s where s.student_code=src.code);

commit;
notify pgrst,'reload schema';

-- Kiểm tra sau khi chạy: 8 lớp mới phải có tổng 164 học sinh.
select c.name as lop, count(s.id) as so_hoc_sinh
from public.app3_classes c
left join public.app3_students s on s.class_id=c.id
where c.name in ('1A1','1A2','1B','1C','2A1','2A2','2B','2C')
group by c.name
order by c.name;

select count(*) as tong_hoc_sinh_8_lop
from public.app3_students s
join public.app3_classes c on c.id=s.class_id
where c.name in ('1A1','1A2','1B','1C','2A1','2A2','2B','2C');
